import { Accordion as BaseAccordion } from "@base-ui/react/accordion";
import type { ComponentPropsWithoutRef, ElementType } from "react";
import { cn } from "../../lib/cn";
import "../../styles/accordion.css";

type StaticClass<T extends ElementType> = Omit<ComponentPropsWithoutRef<T>, "className"> & {
  className?: string;
};

/**
 * Stacked, collapsible sections. Each item needs a unique `value`.
 * Keyboard support (arrows, Home, End, Enter, Space) comes from Base UI.
 *
 * @example
 * <Accordion>
 *   <AccordionItem value="billing">
 *     <AccordionTrigger>Billing</AccordionTrigger>
 *     <AccordionPanel>Invoices go to the owner.</AccordionPanel>
 *   </AccordionItem>
 * </Accordion>
 */
export function Accordion({ className, ...props }: StaticClass<typeof BaseAccordion.Root>) {
  return <BaseAccordion.Root className={cn("eui-accordion", className)} {...props} />;
}

export function AccordionItem({ className, ...props }: StaticClass<typeof BaseAccordion.Item>) {
  return <BaseAccordion.Item className={cn("eui-accordion__item", className)} {...props} />;
}

/** The clickable heading. It wraps the trigger in a heading element for screen readers. */
export function AccordionTrigger({
  className,
  children,
  ...props
}: StaticClass<typeof BaseAccordion.Trigger>) {
  return (
    <BaseAccordion.Header className="eui-accordion__header">
      <BaseAccordion.Trigger className={cn("eui-accordion__trigger", className)} {...props}>
        {children}
        <svg
          className="eui-accordion__chevron"
          width="16"
          height="16"
          viewBox="0 0 16 16"
          fill="none"
          aria-hidden="true"
        >
          <path d="M4 6l4 4 4-4" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" />
        </svg>
      </BaseAccordion.Trigger>
    </BaseAccordion.Header>
  );
}

export function AccordionPanel({ className, ...props }: StaticClass<typeof BaseAccordion.Panel>) {
  return <BaseAccordion.Panel className={cn("eui-accordion__panel", className)} {...props} />;
}

/**
 * Joins class names, skipping falsy values.
 * Kept tiny on purpose: components own their class lists, so no merge step is needed.
 */
export function cn(...inputs: Array<string | false | null | undefined>): string {
  return inputs.filter(Boolean).join(" ");
}

/* Accordion. Items are separated by hairlines, not boxes. The chevron rotates
   and the panel fades in with a small slide. Only transform and opacity animate. */

.eui-accordion {
  display: flex;
  flex-direction: column;
  border-top: var(--eui-border-width) solid var(--eui-color-border);
}

.eui-accordion__item {
  border-bottom: var(--eui-border-width) solid var(--eui-color-border);
}

.eui-accordion__header {
  margin: 0;
  font-size: inherit;
}

.eui-accordion__trigger {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  width: 100%;
  min-height: 44px;
  padding: 12px 0;
  border: 0;
  border-radius: var(--eui-radius-sm);
  background: transparent;
  color: var(--eui-color-fg);
  font-family: inherit;
  font-size: 14px;
  font-weight: 500;
  letter-spacing: -0.011em;
  text-align: left;
  cursor: pointer;
}

.eui-accordion__trigger:focus-visible {
  outline: 2px solid var(--eui-color-ring);
  outline-offset: 2px;
}

.eui-accordion__trigger[data-disabled] {
  opacity: 0.5;
  cursor: not-allowed;
}

.eui-accordion__chevron {
  flex: none;
  color: var(--eui-color-fg-muted);
  transition: transform var(--eui-duration-base) var(--eui-easing-out);
}

.eui-accordion__trigger[aria-expanded="true"] .eui-accordion__chevron {
  transform: rotate(180deg);
}

.eui-accordion__panel {
  padding: 0 0 14px;
  font-size: 14px;
  line-height: 20px;
  color: var(--eui-color-fg-muted);
  animation: eui-accordion-in var(--eui-duration-base) var(--eui-easing-out);
}

@keyframes eui-accordion-in {
  from {
    opacity: 0;
    transform: translateY(-4px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

@media (prefers-reduced-motion: reduce) {
  .eui-accordion__chevron,
  .eui-accordion__panel {
    transition: none;
    animation: none;
  }
}
